import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.CsFjlSKj.js";const c=JSON.parse('{"title":"Advanced Podman","description":"","frontmatter":{},"headers":[],"relativePath":"containers/9-podman-advanced.md","filePath":"containers/9-podman-advanced.md"}'),n={name:"containers/9-podman-advanced.md"};function o(p,a,d,h,l,r){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="advanced-podman" tabindex="-1">Advanced Podman <a class="header-anchor" href="#advanced-podman" aria-label="Permalink to &quot;Advanced Podman&quot;">​</a></h1><p>Podman&#39;s most distinct feature over Docker is its native concept of <strong>Pods</strong>.</p><h2 id="what-is-a-pod" tabindex="-1">What is a Pod? <a class="header-anchor" href="#what-is-a-pod" aria-label="Permalink to &quot;What is a Pod?&quot;">​</a></h2><p>If you are familiar with Kubernetes, a Podman Pod is the exact same concept. A pod is a group of one or more containers that share the same network, IPC, and PID namespaces.</p><p>In Docker, if you want a web server container and a database container to talk to each other, you put them on a bridge network and they resolve each other via DNS.</p><p>In Podman, if you put them in a Pod, they literally share <code>localhost</code>. The web server container can connect to the database container using <code>localhost:5432</code>.</p><h3 id="creating-and-managing-pods" tabindex="-1">Creating and Managing Pods <a class="header-anchor" href="#creating-and-managing-pods" aria-label="Permalink to &quot;Creating and Managing Pods&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Create an empty Pod, mapping port 8080 on the host to the Pod</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-pod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:80</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Add a backend database to the Pod</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-pod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres:15</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Add a frontend API to the Pod (it connects to the DB via localhost!)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-pod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-api-image:latest</span></span></code></pre></div><p>When you inspect <code>podman ps</code>, you will see a hidden &quot;Infra&quot; container (usually using the <code>pause</code> image). This container does nothing but hold the Network Namespace open for the other containers in the pod to attach to.</p><h2 id="migrating-to-kubernetes" tabindex="-1">Migrating to Kubernetes <a class="header-anchor" href="#migrating-to-kubernetes" aria-label="Permalink to &quot;Migrating to Kubernetes&quot;">​</a></h2><p>Because Podman understands the concept of Pods natively, it is designed to be a stepping stone to Kubernetes.</p><p>If you build an architecture using Podman Pods on a single server, and eventually outgrow it and decide to migrate to a massive Kubernetes cluster, Podman will write the Kubernetes YAML files for you!</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate Kubernetes standard YAML from a local Podman pod</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kube</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app-pod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment.yaml</span></span></code></pre></div><p>You can take that <code>deployment.yaml</code> and run <code>kubectl apply -f deployment.yaml</code> directly on an OpenShift or Kubernetes cluster, and it will deploy the exact same architecture.</p><p><em>(Note: Just like <code>generate systemd</code>, the <code>generate kube</code> command is extremely useful for generating boilerplate, but for complex deployments you should write your Kubernetes manifests by hand or use Helm).</em></p><h2 id="auto-updates" tabindex="-1">Auto-Updates <a class="header-anchor" href="#auto-updates" aria-label="Permalink to &quot;Auto-Updates&quot;">​</a></h2><p>Because Podman relies on systemd for lifecycle management, it also integrates with systemd timers to automatically update containers!</p><p>If you add a specific label to your container when running it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;io.containers.autoupdate=registry&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx:latest</span></span></code></pre></div><p>And you enable the systemd auto-update timer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> podman-auto-update.timer</span></span></code></pre></div><p>Podman will wake up every midnight, check the registry for a new <code>nginx:latest</code> image, download it, safely restart the container using the new image, and clean up the old image automatically.</p>`,22)])])}const g=s(n,[["render",o]]);export{c as __pageData,g as default};
